//! The checked-in KVM UAPI constants (src/kvm_abi.rs, generated by
//! ../abi-gen.ts from the encoding rules) against this host's installed
//! Linux headers. Test-time only: the build itself needs no C compiler. The
//! probe is compiled with `$CC` (default `cc`) and prints every constant in
//! the generated file's own line format, so the check is a line-by-line
//! comparison that also catches a constant missing on either side.
#![cfg(all(target_os = "linux", target_arch = "aarch64"))]

use std::{env, fs, process::Command};

const PROBE: &str = r#"#include <linux/kvm.h>
#include <stddef.h>
#include <stdio.h>
#define C(x) printf("pub const " #x ": u64 = %llu;\n", (unsigned long long)(x))
#define O(name, field) printf("pub const " #name ": usize = %zu;\n", offsetof(struct kvm_run, field))
#define R(name, x) printf("pub const " #name ": u64 = %llu;\n", (unsigned long long)(x))
#define CORE(field) (KVM_REG_ARM64 | KVM_REG_SIZE_U64 | KVM_REG_ARM_CORE | (offsetof(struct kvm_regs, field) / 4))
int main(void) {
 C(KVM_GET_API_VERSION); C(KVM_CREATE_VM); C(KVM_CREATE_VCPU);
 C(KVM_GET_VCPU_MMAP_SIZE); C(KVM_SET_USER_MEMORY_REGION); C(KVM_RUN);
 C(KVM_ARM_PREFERRED_TARGET); C(KVM_ARM_VCPU_INIT); C(KVM_GET_ONE_REG); C(KVM_SET_ONE_REG);
 C(KVM_MEM_READONLY); C(KVM_GET_REG_LIST); C(KVM_EXIT_MMIO); C(KVM_ARM_VCPU_PSCI_0_2);
 C(KVM_SET_MP_STATE); C(KVM_GET_MP_STATE); C(KVM_MP_STATE_RUNNABLE); C(KVM_EXIT_SYSTEM_EVENT);
 C(KVM_REG_ARM_TIMER_CNT); C(KVM_REG_ARM64_SYSREG); C(KVM_REG_ARM64); C(KVM_REG_SIZE_U64);
 O(EXIT_REASON, exit_reason); O(IMMEDIATE_EXIT, immediate_exit);
 O(MMIO_ADDR, mmio.phys_addr); O(MMIO_DATA, mmio.data); O(MMIO_LEN, mmio.len); O(MMIO_WRITE, mmio.is_write);
 R(REG_X0, CORE(regs.regs[0])); R(REG_PC, CORE(regs.pc)); R(REG_PSTATE, CORE(regs.pstate));
 R(REG_SCTLR, ARM64_SYS_REG(3, 0, 1, 0, 0));
 C(KVM_CHECK_EXTENSION); C(KVM_ENABLE_CAP); C(KVM_CAP_ARM_NISV_TO_USER); C(KVM_EXIT_ARM_NISV);
 O(NISV_IPA, arm_nisv.fault_ipa);
 return 0;
}
"#;

fn constants(text: &str) -> Vec<String> {
    text.lines()
        .filter(|line| line.starts_with("pub const "))
        .map(str::to_owned)
        .collect()
}

#[test]
fn kvm_abi_matches_host_headers() {
    let dir = env::temp_dir().join(format!("jitk-shard-kvm-abi-{}", std::process::id()));
    fs::create_dir_all(&dir).unwrap();
    let source = dir.join("probe.c");
    let binary = dir.join("probe");
    fs::write(&source, PROBE).unwrap();
    let cc = env::var("CC").unwrap_or_else(|_| "cc".to_owned());
    let mut words = cc.split_whitespace();
    let built = Command::new(words.next().expect("CC is empty"))
        .args(words)
        .arg(&source)
        .arg("-o")
        .arg(&binary)
        .status()
        .unwrap_or_else(|error| panic!("start `{cc}` for the UAPI header probe: {error}"));
    assert!(
        built.success(),
        "`{cc}` failed to build the UAPI header probe"
    );
    let output = Command::new(&binary).output().unwrap();
    assert!(output.status.success(), "UAPI header probe failed");
    fs::remove_dir_all(&dir).unwrap();
    let headers = constants(&String::from_utf8(output.stdout).unwrap());
    let checked_in = constants(include_str!("../src/kvm_abi.rs"));
    assert_eq!(
        headers.len(),
        37,
        "probe printed {} constants",
        headers.len()
    );
    for (index, (host, ours)) in headers.iter().zip(&checked_in).enumerate() {
        assert_eq!(
            host, ours,
            "constant {index}: host headers vs src/kvm_abi.rs"
        );
    }
    assert_eq!(headers.len(), checked_in.len(), "constant count");
}

#[test]
fn kvm_abi_values_reach_the_crate() {
    use jitk_shard::constants::kvm;
    // A spot check that the crate compiles the checked-in file, not a copy.
    assert_eq!(kvm::KVM_GET_API_VERSION, 0xae00);
    assert_eq!(kvm::MMIO_WRITE, 52);
    assert_eq!(kvm::REG_PC - kvm::REG_X0, 64);
}
